<script>
  import { table, createCellAlignmentClasses } from './table'
  import { notEmpty } from '@splendidlabz/utils'

  let klass = null
  export { klass as class }
  export let role = 'table' // Or grid

  // Make it super easy for users to align the grid items
  // Usage: { 2: 'right', 3: 'right' }
  export let alignments = {}

  let alignmentClass = ''
  if (notEmpty(alignments)) {
    alignmentClass = createCellAlignmentClasses(alignments)
  }

  // Future options here will include sortable tables, etc. Maybe do Filtration here and Pagination here as well just for the kick of it?
</script>

<div {role} class="Table {klass} {alignmentClass}" {...$$restProps} use:table>
  <slot />
</div>
